type Ticket = { status: "OPEN" | "CLOSED" };
const tickets: Ticket[] = [{ status: "OPEN" }, { status: "CLOSED" }, { status: "OPEN" }];
export function OpenStats() { const open = tickets.filter(t => t.status === "OPEN").length; return <h2>Otwarte: {open}</h2>; }

function plural(n: number): string {
  if (n === 1) return "ticket";
  const last = n % 10, lastTwo = n % 100;
  return last >= 2 && last <= 4 && !(lastTwo >= 12 && lastTwo <= 14) ? "tickety" : "ticketów";
}
