type Ticket = { id: number; status: "OPEN" | "CLOSED" };
type Props = { tickets: Ticket[]; dateLabel: string };
function plural(n: number): string { if (n === 1) return "ticket"; const d = n % 10, h = n % 100; return d >= 2 && d <= 4 && !(h >= 12 && h <= 14) ? "tickety" : "ticketów"; }
export function Summary({ tickets, dateLabel }: Props) {
  const total = tickets.length;
  const open = tickets.filter(t => t.status === "OPEN").length;
  const percent = total === 0 ? 0 : Math.round(open / total * 100);
  return <main className="app-main"><h1>Otwarte: {open}</h1><p>Stan na {dateLabel} · wszystkich: {total}</p><p>{open} {plural(open)} · {percent}%</p></main>;
}
